def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (ignore it)
        if '+' in version:
            version = version.split('+')[0]

        # Split pre-release
        if '-' in version:
            base, prerelease = version.split('-', 1)
        else:
            base = version
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_parts = prerelease.split('.')
            prerelease_parsed = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_parsed.append((0, int(part)))
                else:
                    prerelease_parsed.append((1, part))
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def compare_key(version):
        major, minor, patch, prerelease = parse_version(version)

        # Versions with pre-release sort before those without
        # Use empty list for no pre-release (sorts after any pre-release)
        if prerelease is None:
            prerelease_key = (1, [])
        else:
            prerelease_key = (0, prerelease)

        return (major, minor, patch, prerelease_key)

    return sorted(versions, key=compare_key)

